/* Card Component Styles */

/* Base card styles */
.card {
  background-color: white;
  border-radius: 0.75rem;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
  overflow: hidden;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

/* Card hover effect */
.card:hover {
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

/* Card header */
.card-header {
  padding: 1.25rem;
  border-bottom: 1px solid #e5e7eb;
}

.card-header-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Card title */
.card-title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  color: #111827;
  line-height: 1.25;
}

/* Card subtitle */
.card-subtitle {
  margin: 0.25rem 0 0;
  font-size: 0.875rem;
  color: #6b7280;
}

/* Card body */
.card-body {
  padding: 1.25rem;
  flex: 1;
}

/* Card text */
.card-text {
  margin: 0;
  color: #374151;
  line-height: 1.6;
}

/* Card footer */
.card-footer {
  padding: 1.25rem;
  border-top: 1px solid #e5e7eb;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  justify-content: space-between;
}

/* Card buttons */
.card-button {
  padding: 0.5rem 1rem;
  background-color: #3b82f6;
  color: white;
  border: none;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s;
}

.card-button:hover {
  background-color: #2563eb;
}

.card-button:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.card-button-primary {
  background-color: #3b82f6;
}

.card-button-primary:hover {
  background-color: #2563eb;
}

.card-button-secondary {
  background-color: transparent;
  color: #3b82f6;
  border: 1px solid #3b82f6;
}

.card-button-secondary:hover {
  background-color: #eff6ff;
}

/* Card with image */
.card-with-image .card-image-wrapper {
  width: 100%;
  height: 200px;
  overflow: hidden;
}

.card-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.card:hover .card-image {
  transform: scale(1.05);
}

/* Horizontal card */
.card-horizontal {
  flex-direction: row;
}

.card-horizontal .card-image-wrapper {
  width: 200px;
  height: auto;
  flex-shrink: 0;
}

.card-horizontal .card-content {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.card-horizontal .card-header {
  border-bottom: none;
}

.card-horizontal .card-footer {
  border-top: none;
  padding-top: 0;
}

/* Interactive card */
.card-interactive {
  cursor: pointer;
  position: relative;
}

.card-interactive:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.card-interactive::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, transparent 0%, rgba(59, 130, 246, 0.05) 100%);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.card-interactive:hover::before {
  opacity: 1;
}

/* Card badge */
.card-badge {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  background-color: #10b981;
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 0.25rem;
  text-transform: uppercase;
}

/* Card tags */
.card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.card-tag {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background-color: #f3f4f6;
  color: #4b5563;
  font-size: 0.75rem;
  border-radius: 9999px;
}

/* Card meta */
.card-meta {
  font-size: 0.875rem;
  color: #6b7280;
}

/* Card icon button */
.card-icon-button {
  padding: 0.5rem;
  background-color: transparent;
  border: none;
  border-radius: 0.375rem;
  cursor: pointer;
  color: #6b7280;
  transition: all 0.2s;
}

.card-icon-button:hover {
  background-color: #f3f4f6;
  color: #ef4444;
}

.card-icon-button:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Card actions */
.card-actions {
  display: flex;
  gap: 0.5rem;
}

.card-action-button {
  padding: 0.375rem;
  background-color: transparent;
  border: none;
  border-radius: 0.25rem;
  cursor: pointer;
  color: #6b7280;
  transition: all 0.2s;
}

.card-action-button:hover {
  background-color: #f3f4f6;
  color: #374151;
}

/* Minimal card */
.card-minimal {
  box-shadow: none;
  border: 1px solid #e5e7eb;
}

.card-minimal:hover {
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

/* Card showcase container */
.card-showcase {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  padding: 2rem;
  background-color: #f9fafb;
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .card {
    background-color: #1f2937;
    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.3);
  }

  .card-header,
  .card-footer {
    border-color: #374151;
  }

  .card-title {
    color: #f3f4f6;
  }

  .card-subtitle,
  .card-meta {
    color: #9ca3af;
  }

  .card-text {
    color: #d1d5db;
  }

  .card-tag {
    background-color: #374151;
    color: #d1d5db;
  }

  .card-minimal {
    border-color: #374151;
  }

  .card-showcase {
    background-color: #111827;
  }
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .card-horizontal {
    flex-direction: column;
  }

  .card-horizontal .card-image-wrapper {
    width: 100%;
    height: 150px;
  }

  .card-showcase {
    grid-template-columns: 1fr;
    padding: 1rem;
  }

  .card-header,
  .card-body,
  .card-footer {
    padding: 1rem;
  }
}

