/* Modal Component Styles */

/* Modal container */
.modal {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

/* Modal open state */
.modal.modal-open {
  opacity: 1;
  visibility: visible;
}

/* Modal backdrop */
.modal-backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  transition: opacity 0.3s ease;
}

/* Modal container wrapper */
.modal-container {
  position: relative;
  max-width: 32rem;
  width: 100%;
  max-height: 90vh;
  display: flex;
  transform: scale(0.95);
  transition: transform 0.3s ease;
}

.modal-open .modal-container {
  transform: scale(1);
}

/* Modal content */
.modal-content {
  background-color: white;
  border-radius: 0.75rem;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  width: 100%;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}

/* Modal header */
.modal-header {
  padding: 1.5rem;
  border-bottom: 1px solid #e5e7eb;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.modal-header-sticky {
  position: sticky;
  top: 0;
  background-color: white;
  z-index: 10;
}

.modal-header-danger {
  border-bottom-color: #fecaca;
  background-color: #fef2f2;
}

/* Modal title */
.modal-title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  color: #111827;
  line-height: 1.25;
}

/* Modal close button */
.modal-close {
  padding: 0.5rem;
  background-color: transparent;
  border: none;
  border-radius: 0.375rem;
  cursor: pointer;
  color: #6b7280;
  transition: all 0.2s;
  margin-left: auto;
}

.modal-close:hover {
  background-color: #f3f4f6;
  color: #374151;
}

.modal-close:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Modal icon */
.modal-icon {
  margin-right: 1rem;
  padding: 0.75rem;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.modal-icon-danger {
  background-color: #fecaca;
  color: #dc2626;
}

/* Modal body */
.modal-body {
  padding: 1.5rem;
  flex: 1;
  overflow-y: auto;
}

.modal-body-scrollable {
  max-height: 400px;
  overflow-y: auto;
}

.modal-body p {
  margin: 0 0 1rem;
  color: #374151;
  line-height: 1.6;
}

.modal-body p:last-child {
  margin-bottom: 0;
}

.modal-body h3 {
  margin: 1.5rem 0 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  color: #111827;
}

.modal-body h3:first-child {
  margin-top: 0;
}

/* Modal footer */
.modal-footer {
  padding: 1.5rem;
  border-top: 1px solid #e5e7eb;
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
  flex-shrink: 0;
}

.modal-footer-center {
  justify-content: center;
}

.modal-footer-sticky {
  position: sticky;
  bottom: 0;
  background-color: white;
  z-index: 10;
}

/* Modal buttons */
.modal-button {
  padding: 0.625rem 1.25rem;
  border: none;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}

.modal-button:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.modal-button-primary {
  background-color: #3b82f6;
  color: white;
}

.modal-button-primary:hover {
  background-color: #2563eb;
}

.modal-button-secondary {
  background-color: white;
  color: #374151;
  border: 1px solid #d1d5db;
}

.modal-button-secondary:hover {
  background-color: #f9fafb;
}

.modal-button-danger {
  background-color: #dc2626;
  color: white;
}

.modal-button-danger:hover {
  background-color: #b91c1c;
}

/* Modal trigger buttons */
.modal-trigger {
  padding: 0.625rem 1.25rem;
  background-color: #3b82f6;
  color: white;
  border: none;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s;
  margin: 0.5rem;
}

.modal-trigger:hover {
  background-color: #2563eb;
}

.modal-trigger:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

/* Form elements in modal */
.modal-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.form-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: #374151;
}

.form-input,
.form-textarea {
  padding: 0.625rem;
  border: 1px solid #d1d5db;
  border-radius: 0.375rem;
  font-size: 0.875rem;
  transition: all 0.2s;
  font-family: inherit;
}

.form-input:focus,
.form-textarea:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.form-textarea {
  resize: vertical;
  min-height: 100px;
}

/* Modal size variants */
.modal-small .modal-container {
  max-width: 24rem;
}

.modal-content-wide {
  max-width: 40rem;
}

.modal-fullscreen {
  padding: 0;
}

.modal-fullscreen .modal-container {
  max-width: 100%;
  width: 100%;
  height: 100%;
  max-height: 100vh;
}

.modal-fullscreen .modal-content {
  border-radius: 0;
  height: 100%;
  max-height: 100vh;
}

/* Animation classes */
@keyframes modalSlideIn {
  from {
    transform: translateY(-20px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.modal-open .modal-content {
  animation: modalSlideIn 0.3s ease;
}

/* Prevent body scroll when modal is open */
body.modal-body-lock {
  overflow: hidden;
}

/* Modal showcase container */
.modal-showcase {
  padding: 2rem;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  .modal-content {
    background-color: #1f2937;
    color: #f3f4f6;
  }

  .modal-header {
    border-bottom-color: #374151;
  }

  .modal-header-sticky {
    background-color: #1f2937;
  }

  .modal-title {
    color: #f3f4f6;
  }

  .modal-close {
    color: #9ca3af;
  }

  .modal-close:hover {
    background-color: #374151;
    color: #d1d5db;
  }

  .modal-body p {
    color: #d1d5db;
  }

  .modal-body h3 {
    color: #f3f4f6;
  }

  .modal-footer {
    border-top-color: #374151;
  }

  .modal-footer-sticky {
    background-color: #1f2937;
  }

  .modal-button-secondary {
    background-color: #374151;
    color: #f3f4f6;
    border-color: #4b5563;
  }

  .modal-button-secondary:hover {
    background-color: #4b5563;
  }

  .form-label {
    color: #d1d5db;
  }

  .form-input,
  .form-textarea {
    background-color: #374151;
    color: #f3f4f6;
    border-color: #4b5563;
  }
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .modal {
    padding: 0;
  }

  .modal-content {
    border-radius: 0;
    min-height: 100vh;
    max-height: 100vh;
  }

  .modal-container {
    max-width: 100%;
    max-height: 100vh;
  }

  .modal-header {
    padding: 1rem;
  }

  .modal-body {
    padding: 1rem;
  }

  .modal-footer {
    padding: 1rem;
    flex-direction: column;
  }

  .modal-button {
    width: 100%;
  }
}

